const canvas=document.querySelector('canvas'),c=canvas.getContext('2d'),keys={},$=s=>document.getElementById(s);let fighters,shots=[],sparks=[],running=false,paused=false,time=60,last=0,shake=0,aiClock=0;
function create(x,id){return{x,y:510,vy:0,hp:100,en:60,id,dir:id?-1:1,cd:0,attack:0,type:'',block:false,hit:0,walk:0}}
function reset(){fighters=[create(330,0),create(870,1)];shots=[];sparks=[];time=60;aiClock=0;running=true;paused=false;$('overlay').classList.add('hidden');$('pause').textContent='Pausa'}
function end(text){running=false;$('title').textContent=text;$('desc').textContent='Il prossimo scontro ti aspetta. Premi per riprovare.';$('start').textContent='RIVINCITA →';$('overlay').classList.remove('hidden')}
function damage(a,b,n){if(b.hit>0)return;let blocked=b.block&&b.y>=508&&b.dir===-a.dir;b.hp=Math.max(0,b.hp-(blocked?n*.16:n));b.hit=.18;b.x=Math.max(65,Math.min(1135,b.x+a.dir*(blocked?5:20)));shake=blocked?2:9;for(let j=0;j<14;j++)sparks.push({x:b.x,y:b.y-120,vx:(Math.random()-.5)*400,vy:(Math.random()-.5)*400,t:.35,color:blocked?'#b8dcff':'#ffad6a'});if(b.hp<=0)end(a.id?'SHIN VINCE':'ONI VINCE')}
function attack(f,type){if(!running||paused||f.cd>0||f.hit>0||f.block)return;if(type==='special'&&f.en<30)return;f.type=type;f.attack=.28;f.cd=type==='special'?.75:type==='kick'?.55:.35;if(type==='special'){f.en-=30;shots.push({x:f.x+f.dir*55,y:f.y-125,dir:f.dir,id:f.id})}else{let b=fighters[1-f.id];if(Math.abs(b.x-f.x)<(type==='kick'?160:115)&&Math.abs(b.y-f.y)<85&&(b.x-f.x)*f.dir>0)damage(f,b,type==='kick'?12:7)}}
function toggle(){if(!running)return;paused=!paused;$('pause').textContent=paused?'Riprendi':'Pausa';$('status').textContent=paused?'SCONTRO IN PAUSA':'ARENA 01 / ECLISSI SCARLATTA'}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(!keys[k]){if(k==='p')toggle();let map={u:[0,'punch'],i:[0,'kick'],o:[0,'special'],j:[1,'punch'],k:[1,'kick'],l:[1,'special']};if(map[k]&&(map[k][0]===0||$('mode').value==='local'))attack(fighters[map[k][0]],map[k][1])}keys[k]=true});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);if(running&&!paused)toggle()});document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true;let m={u:'punch',i:'kick',o:'special'};if(m[b.dataset.key])attack(fighters[0],m[b.dataset.key])});for(let evt of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(evt,()=>keys[b.dataset.key]=false)});$('start').onclick=reset;$('reset').onclick=reset;$('pause').onclick=toggle;$('mode').onchange=()=>{if(running)reset()};
function update(dt){if(!running||paused)return;time-=dt;if(time<=0){time=0;end(fighters[0].hp===fighters[1].hp?'PAREGGIO':fighters[0].hp>fighters[1].hp?'ONI VINCE':'SHIN VINCE');return}fighters.forEach((f,i)=>{let b=fighters[1-i];f.dir=b.x>f.x?1:-1;f.cd=Math.max(0,f.cd-dt);f.attack=Math.max(0,f.attack-dt);f.hit=Math.max(0,f.hit-dt);f.en=Math.min(100,f.en+dt*7);let left=i?'arrowleft':'a',right=i?'arrowright':'d',up=i?'arrowup':'w',down=i?'arrowdown':'s';let move=(keys[right]?1:0)-(keys[left]?1:0),jump=keys[up];f.block=!!keys[down];if(i&&$('mode').value==='cpu'){aiClock-=dt;let dist=Math.abs(b.x-f.x);move=dist>120?f.dir:dist<83?-f.dir:0;f.block=b.attack>0&&Math.random()<.7;jump=false;if(aiClock<=0){aiClock=.28+Math.random()*.5;f.block=false;attack(f,dist>220?'special':Math.random()<.5?'punch':'kick');jump=Math.random()<.16}}if(f.hit<=0&&!f.block&&f.attack<=0){f.x+=move*240*dt;f.walk+=Math.abs(move)*dt*12;if(jump&&f.y>=510)f.vy=-680}f.vy+=1700*dt;f.y+=f.vy*dt;if(f.y>510){f.y=510;f.vy=0}f.x=Math.max(65,Math.min(1135,f.x))});let a=fighters[0],b=fighters[1];if(Math.abs(a.x-b.x)<72&&Math.abs(a.y-b.y)<130){let mid=(a.x+b.x)/2,dir=a.x<b.x?1:-1;a.x=mid-36*dir;b.x=mid+36*dir}shots=shots.filter(s=>{s.x+=s.dir*620*dt;let target=fighters[1-s.id];if(Math.abs(s.x-target.x)<40&&Math.abs(s.y-(target.y-120))<85){damage(fighters[s.id],target,18);return false}return s.x>-30&&s.x<1230});sparks.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.t-=dt});sparks=sparks.filter(p=>p.t>0);shake*=.82}
function line(points,color,width){c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.stroke()}
function fighter(f){c.save();c.translate(f.x,f.y);c.scale(f.dir,1);let bob=Math.sin(f.walk)*3,id=f.id,skin='#b87952',power=id?'#69cfff':'#b85dff',atk=f.attack>0,kick=atk&&f.type==='kick',punch=atk&&f.type!=='kick';c.shadowColor=power;c.shadowBlur=f.hit?35:12;c.fillStyle='#0009';c.beginPath();c.ellipse(0,3,48,10,0,0,7);c.fill();c.translate(0,bob);let stride=Math.sin(f.walk)*14;line([[-17,-94],[-22-stride,-48],[-27-stride,0]],'#22212b',29);line([[17,-94],[kick?81:25+stride,kick?-85:-45],[kick?126:30+stride,kick?-95:0]],'#24222c',29);line([[-40-stride,0],[-13-stride,0]],id?'#eee5d9':'#b72e39',17);line([[kick?115:18+stride,kick?-95:0],[kick?140:47+stride,kick?-95:0]],id?'#eee5d9':'#b72e39',17);c.fillStyle=skin;c.beginPath();c.moveTo(-30,-179);c.lineTo(29,-179);c.lineTo(23,-93);c.lineTo(-22,-93);c.closePath();c.fill();c.strokeStyle='#714937';c.lineWidth=2;for(let j=0;j<3;j++){c.beginPath();c.moveTo(-15,-148+j*18);c.lineTo(15,-148+j*18);c.stroke()}line([[-29,-172],[-45,-133],[-25,-115]],skin,21);line([[28,-171],[punch?62:f.block?45:47,punch?-159:f.block?-188:-140],[punch?110:f.block?30:40,punch?-162:f.block?-204:-111]],skin,21);line([[-32,-124],[-25,-115]],'#171720',22);line([[punch?92:f.block?34:41,punch?-162:f.block?-199:-122],[punch?111:f.block?30:40,punch?-162:f.block?-204:-110]],id?'#23232a':'#481f35',22);c.fillStyle=skin;c.beginPath();c.ellipse(0,-204,24,29,0,0,7);c.fill();c.fillStyle='#19171c';c.beginPath();c.moveTo(-25,-212);for(let j=0;j<7;j++)c.lineTo(-24+j*8,-237-(j%2)*10);c.lineTo(26,-209);c.fill();if(id){line([[-23,-218],[24,-218]],'#dddde4',9);line([[-22,-218],[-70,-227],[-92,-215]],'#dddde4',6)}else{line([[-18,-230],[-31,-259],[-32,-268]],'#bca18b',8);line([[18,-230],[32,-259],[32,-268]],'#bca18b',8);c.strokeStyle='#24151e';c.lineWidth=5;for(let j=0;j<3;j++){c.beginPath();c.moveTo(-25,-169+j*14);c.lineTo(-7,-158+j*14);c.stroke()}}c.shadowBlur=16;c.shadowColor=power;c.fillStyle=power;c.fillRect(8,-207,10,4);c.restore()}
function draw(t){let bg=c.createLinearGradient(0,0,0,600);bg.addColorStop(0,'#11101f');bg.addColorStop(.7,'#401623');bg.addColorStop(1,'#0d0d16');c.fillStyle=bg;c.fillRect(0,0,1200,600);c.save();c.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);c.shadowColor='#ff302e';c.shadowBlur=70;c.fillStyle='#c42c36';c.beginPath();c.arc(600,200,126,0,7);c.fill();c.shadowBlur=0;c.fillStyle='#1a1020';c.beginPath();c.arc(614,183,119,0,7);c.fill();for(let j=0;j<14;j++){let x=j*100-30,h=110+(Math.sin(j*87)+1)*100;c.fillStyle=j%2?'#191421':'#241825';c.fillRect(x,510-h,50,h);c.fillStyle='#6a273a';c.fillRect(x+15,510-h+20,3,Math.min(80,h-20))}c.fillStyle='#211923';c.fillRect(0,510,1200,90);c.strokeStyle='#5c3440';c.lineWidth=1;for(let j=0;j<12;j++){c.beginPath();c.moveTo(600,510);c.lineTo((j-3)*240,600);c.stroke()}for(let y of [525,550,590]){c.beginPath();c.moveTo(0,y);c.lineTo(1200,y);c.stroke()}for(let j=0;j<32;j++){let x=(j*173+t*12)%1200,y=510-((j*83+t*23)%470);c.fillStyle='#f3766766';c.fillRect(x,y,2,3)}fighters.forEach(fighter);shots.forEach(s=>{c.shadowColor=s.id?'#5ed9ff':'#b142ff';c.shadowBlur=30;let g=c.createRadialGradient(s.x,s.y,0,s.x,s.y,27);g.addColorStop(0,'white');g.addColorStop(.3,s.id?'#6fe2ff':'#ce5cff');g.addColorStop(1,'transparent');c.fillStyle=g;c.beginPath();c.ellipse(s.x,s.y,38,24,0,0,7);c.fill()});c.shadowBlur=0;sparks.forEach(p=>{c.fillStyle=p.color;c.fillRect(p.x,p.y,4,4)});c.restore();fighters.forEach((f,i)=>{$('hp'+i).style.width=f.hp+'%';$('en'+i).style.width=f.en+'%'});$('timer').textContent=Math.ceil(time).toString().padStart(2,'0');if(paused){c.fillStyle='#090812b0';c.fillRect(0,0,1200,600);c.fillStyle='white';c.textAlign='center';c.font='bold 40px system-ui';c.fillText('PAUSA',600,310)}}fighters=[create(330,0),create(870,1)];function loop(ms){let dt=Math.min((ms-last)/1000,.035);last=ms;update(dt);draw(ms/1000);requestAnimationFrame(loop)}requestAnimationFrame(loop);
